class Solution {
public:
    int matrixSum(vector<vector<int>>& nums) {
        for (auto& row : nums) sort(row.begin(), row.end());
        int ans = 0;
        for (size_t i = 0; i < nums[0].size(); ++i) {
            int mx = 0;
            for (auto& row : nums) mx = max(mx, row[i]);
            ans += mx;
        }
        return ans;
    }
};

