import heapq
class Solution:
    def matrixSum(self, nums: List[List[int]]) -> int:
        heaps = []
        for row in nums:
            h = [-x for x in row]
            heapq.heapify(h)
            heaps.append(h)
        ans = 0
        for _ in range(len(nums[0])):
            ans -= min(h[0] for h in heaps)
            for h in heaps:
                heapq.heappop(h)
        return ans

