class Solution {
public:
    int matrixSum(vector<vector<int>>& nums) {
        vector<priority_queue<int>> heaps;
        for (auto& row : nums) heaps.emplace_back(less<int>(), row);
        int ans = 0;
        for (size_t r = 0; r < nums[0].size(); ++r) {
            int mx = 0;
            for (auto& h : heaps) { mx = max(mx, h.top()); h.pop(); }
            ans += mx;
        }
        return ans;
    }
};

