class Solution {
    public int matrixSum(int[][] nums) {
        List<PriorityQueue<Integer>> heaps = new ArrayList<>();
        for (int[] row : nums) {
            PriorityQueue<Integer> h = new PriorityQueue<>(Collections.reverseOrder());
            for (int x : row) h.offer(x);
            heaps.add(h);
        }
        int ans = 0;
        for (int r = 0; r < nums[0].length; ++r) {
            int mx = 0;
            for (PriorityQueue<Integer> h : heaps) mx = Math.max(mx, h.poll());
            ans += mx;
        }
        return ans;
    }
}

